INSERT INTO `bw_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(3852, 471, 'превью', 'Вопросы антимагнитной защиты часов всегда в центре внимания конструкторского бюро компании Ball. Ведь от этого во многом зависит точность хода. Модель Magneto S являются единственными в мире часами, способными выдержать магнитное поле до 80 000 А/м.'),
(3853, 471, '_превью', 'field_5d53cdc5506b1'),
(3854, 497, 'description', ''),
(3855, 497, '_description', 'field_5bc9a4dfe584e'),
(3856, 497, 'обложка', '389'),
(3857, 497, '_обложка', 'field_5bcb31c9af414'),
(3858, 497, 'превью', 'Вопросы антимагнитной защиты часов всегда в центре внимания конструкторского бюро компании Ball. Ведь от этого во многом зависит точность хода. Модель Magneto S являются единственными в мире часами, способными выдержать магнитное поле до 80 000 А/м.'),
(3859, 497, '_превью', 'field_5d53cdc5506b1'),
(3860, 470, 'превью', 'При активном использовании часов (например игра в гольф, стрельба) балансовая пружина подвергается серьезным колебаниям. В результате возникает серьезная погрешность точности хода часов. Более того могут произойти более серьезные нарушения в системе автоподзавода.Технология, разработанная в Ball решает эту проблему.'),
(3861, 470, '_превью', 'field_5d53cdc5506b1'),
(3862, 498, 'description', ''),
(3863, 498, '_description', 'field_5bc9a4dfe584e'),
